1 | /**
2 |  * CIRQ Standard API Client
3 |  * Features:
4 |  * - Base path /api/v1
5 |  * - Generated X-Request-Id header
6 |  * - Bearer token attachment
7 |  * - Standard ApiError mapping with requestId
8 |  */
9 | 
10 | export interface ApiErrorPayload {
11 |   code: string;
12 |   message: string;
13 |   requestId?: string;
14 | }
15 | 
16 | export class ApiError extends Error {
17 |   public code: string;
18 |   public requestId?: string;
19 |   public status: number;
20 | 
21 |   constructor(status: number, payload: ApiErrorPayload) {
22 |     super(payload.message || `API Request failed with status ${status}`);
23 |     this.name = 'ApiError';
24 |     this.status = status;
25 |     this.code = payload.code || 'UNKNOWN_ERROR';
26 |     this.requestId = payload.requestId;
27 |   }
28 | }
29 | 
30 | export const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || '/api/v1';
31 | 
32 | export async function request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
33 |   const requestId = `req-${Math.random().toString(36).substring(2, 10)}`;
34 |   const headers = new Headers(options.headers || {});
35 | 
36 |   if (!headers.has('Content-Type') && !(options.body instanceof FormData)) {
37 |     headers.set('Content-Type', 'application/json');
38 |   }
39 |   headers.set('X-Request-Id', requestId);
40 | 
41 |   // Attach session token if stored
42 |   const token = typeof window !== 'undefined' ? sessionStorage.getItem('cirq_auth_token') : null;
43 |   if (token && !headers.has('Authorization')) {
44 |     headers.set('Authorization', `Bearer ${token}`);
45 |   }
46 | 
47 |   const url = endpoint.startsWith('http') ? endpoint : `${API_BASE_URL}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;
48 | 
49 |   try {
50 |     const response = await fetch(url, {
51 |       ...options,
52 |       headers
53 |     });
54 | 
55 |     const responseRequestId = response.headers.get('X-Request-Id') || requestId;
56 | 
57 |     if (!response.ok) {
58 |       let errPayload: ApiErrorPayload = {
59 |         code: `HTTP_${response.status}`,
60 |         message: response.statusText,
61 |         requestId: responseRequestId
62 |       };
63 | 
64 |       try {
65 |         const json = await response.json();
66 |         if (json && json.error) {
67 |           errPayload = {
68 |             code: json.error.code || errPayload.code,
69 |             message: json.error.message || errPayload.message,
70 |             requestId: json.error.requestId || responseRequestId
71 |           };
72 |         }
73 |       } catch {
74 |         // Response was not JSON
75 |       }
76 | 
77 |       throw new ApiError(response.status, errPayload);
78 |     }
79 | 
80 |     if (response.status === 204) {
81 |       return {} as T;
82 |     }
83 | 
84 |     return await response.json();
85 |   } catch (error) {
86 |     if (error instanceof ApiError) {
87 |       throw error;
88 |     }
89 |     // Network or client-side failure (offline / DNS)
90 |     throw new ApiError(0, {
91 |       code: 'NETWORK_OFFLINE',
92 |       message: error instanceof Error ? error.message : 'Network connection failed.',
93 |       requestId
94 |     });
95 |   }
96 | }
