101 | function computeCentroidAndBbox(coordinates: any): { centroid: [number, number]; bounds: [number, number, number, number] } {
102 |   let minLng = Infinity;
103 |   let maxLng = -Infinity;
104 |   let minLat = Infinity;
105 |   let maxLat = -Infinity;
106 |   let sumLng = 0;
107 |   let sumLat = 0;
108 |   let totalPts = 0;
109 | 
110 |   const traverse = (coords: any) => {
111 |     if (typeof coords[0] === 'number' && typeof coords[1] === 'number') {
112 |       const lng = coords[0];
113 |       const lat = coords[1];
114 |       minLng = Math.min(minLng, lng);
115 |       maxLng = Math.max(maxLng, lng);
116 |       minLat = Math.min(minLat, lat);
117 |       maxLat = Math.max(maxLat, lat);
118 |       sumLng += lng;
119 |       sumLat += lat;
120 |       totalPts++;
121 |     } else {
122 |       for (const item of coords) {
123 |         traverse(item);
124 |       }
125 |     }
126 |   };
127 | 
128 |   traverse(coordinates);
129 | 
130 |   const centroid: [number, number] = totalPts > 0
131 |     ? [sumLng / totalPts, sumLat / totalPts]
132 |     : [76.77, 18.35];
133 | 
134 |   const bounds: [number, number, number, number] = [
135 |     minLng === Infinity ? 76.2 : minLng,
136 |     minLat === Infinity ? 17.87 : minLat,
137 |     maxLng === -Infinity ? 77.34 : maxLng,
138 |     maxLat === -Infinity ? 18.84 : maxLat
139 |   ];
140 | 
141 |   return { centroid, bounds };
